function DependenciesView() {
  const [data, setData] = useState<any[]>([]); const [key, setKey] = useState(0); const reload = () => setKey(k => k + 1); const { showToast, showModal } = useUI()
  useEffect(() => { setData(DS.getAll('pm_dependency')) }, [key])
  const columns: ColumnDef[] = [{ field: 'pm_summary', label: 'Dependency Summary' },{ field: 'pm_detail', label: 'Detail' },{ field: 'pm_riskid', label: 'Risk', render: (r: any) => DS.getLookupName('pm_risk', r.pm_riskid) }]
  const actions: ActionDef[] = [{ id: 'edit', label: '✏️ Edit', cls: 'edit', onClick: (id) => { const rec = DS.getById('pm_dependency', id); const risks = DS.getAll('pm_risk'); showModal({ title: 'Edit Dependency', fields: getFields('pm_dependency').filter(f => f.name !== 'pm_riskid'), data: rec, extraContent: (<div><label>Risk</label><select id="depRisk" data-extra defaultValue={rec.pm_riskid || ''}><option value="">None</option>{risks.map((r: any) => <option key={r.id} value={r.id}>{r.pm_summary}</option>)}</select></div>), onSave: (fd) => { fd.pm_riskid = (document.getElementById('depRisk') as HTMLSelectElement).value; DS.update('pm_dependency', id, fd); reload(); showToast('Dependency updated!') }, onDelete: () => { DS.delete('pm_dependency', id); reload(); showToast('Dependency deleted!') } }) } },{ id: 'delete', label: '🗑️', cls: 'delete', onClick: (id) => { if (confirm('Delete this dependency?')) { DS.delete('pm_dependency', id); reload(); showToast('Dependency deleted!') } } }]
  return (<div><div className="dashboard-header"><h2>🔗 Dependencies</h2><button className="btn btn-primary" onClick={() => { const risks = DS.getAll('pm_risk'); showModal({ title: 'New Dependency', fields: getFields('pm_dependency').filter(f => f.name !== 'pm_riskid'), extraContent: (<div><label>Risk</label><select id="depRisk" data-extra><option value="">None</option>{risks.map((r: any) => <option key={r.id} value={r.id}>{r.pm_summary}</option>)}</select></div>), onSave: (fd) => { fd.pm_riskid = (document.getElementById('depRisk') as HTMLSelectElement).value; DS.create('pm_dependency', fd); reload(); showToast('Dependency created!') } }) }}>+ New Dependency</button></div><StatsCards stats={[{ value: data.length, label: 'Dependencies' }]} /><SearchBar /><DataTable columns={columns} data={data} actions={actions} /></div>)
}

function ReleasesView() {
  const [data, setData] = useState<any[]>([]); const [expanded, setExpanded] = useState<Set<string>>(new Set()); const [key, setKey] = useState(0); const reload = () => setKey(k => k + 1); const { showToast, showModal } = useUI()
  useEffect(() => { setData(DS.getAll('pm_release')) }, [key])
  const items = useMemo(() => DS.getAll('pm_releaseitem'), [key]); const stories = useMemo(() => DS.getAll('pm_userstory'), [key])
  const toggle = (id: string) => { setExpanded(prev => { const s = new Set(prev); if (s.has(id)) s.delete(id); else s.add(id); return s }) }
  const { term } = useSearch()
  const filtered = term ? data.filter((r: any) => Object.values(r).some(v => String(v ?? '').toLowerCase().includes(term.toLowerCase()))) : data

  const changeReleaseStatus = (id: string, newStatus: string) => { DS.update('pm_release', id, { pm_status: newStatus }); reload(); showToast(`Release ${newStatus}!`) }
  const openRelease = (id: string) => changeReleaseStatus(id, 'Open')
  const reviewRelease = (id: string) => changeReleaseStatus(id, 'In Review')
  const completeRelease = (id: string) => changeReleaseStatus(id, 'Released')

  const showSignoffModal = (riId: string) => { const ri = DS.getById('pm_releaseitem', riId); if (!ri) return; const story = DS.getById('pm_userstory', ri.pm_userstory); const ssConfigs = DS.query('pm_config', { pm_type: 'signoff_status' }); showModal({ title: `Signoff: ${story?.pm_detail?.substring(0, 50) || '—'}`, fields: [{ name: 'pm_signoff_status', label: 'Decision', type: 'choice', choices: ssConfigs.map((c: any) => c.pm_name), required: true },{ name: 'pm_signoff_note', label: 'Note', type: 'text' }], data: { pm_signoff_status: ri.pm_signoff_status === 'Pending' ? '' : ri.pm_signoff_status, pm_signoff_note: ri.pm_signoff_note || '' }, onSave: (fd) => { DS.update('pm_releaseitem', riId, { pm_signoff_status: fd.pm_signoff_status, pm_signoff_note: fd.pm_signoff_note || '', pm_signoff_by: 'PO', pm_signoff_date: new Date().toISOString().slice(0, 10) }); reload(); showToast('Signoff recorded!') } }) }

  const registerStory = (relId: string) => { const unregistered = stories.filter((s: any) => !items.some((ri: any) => ri.pm_release === relId && ri.pm_userstory === s.id)); showModal({ title: 'Register User Story', fields: [], extraContent: (<div>{unregistered.length === 0 ? <p>All stories already registered</p> : (<div><label>User Story</label><select id="regStory" data-extra>{unregistered.map((s: any) => <option key={s.id} value={s.id}>{s.pm_detail?.substring(0, 80)}</option>)}</select><label>Developer</label><input type="text" id="regDev" data-extra placeholder="Your name" /></div>)}</div>), onSave: () => { const sid = (document.getElementById('regStory') as HTMLSelectElement)?.value; const dev = (document.getElementById('regDev') as HTMLInputElement)?.value; if (!sid) return; DS.create('pm_releaseitem', { pm_release: relId, pm_userstory: sid, pm_signoff_status: 'Pending', pm_registered_by: dev || 'Dev', pm_registered_date: new Date().toISOString().slice(0, 10) }); reload(); showToast('Story registered!') } }) }

  return (
    <div>
      <div className="dashboard-header"><h2>🚀 Release Management</h2><button className="btn btn-primary" onClick={() => showModal({ title: 'New Release', fields: getFields('pm_release'), onSave: (fd) => { fd.pm_status = 'Draft'; DS.create('pm_release', fd); reload(); showToast('Release created!') } })}>+ New Release</button></div>
      <StatsCards stats={[{ value: data.length, label: 'Releases' },{ value: data.filter((r: any) => r.pm_status === 'Open').length, label: 'Open' },{ value: data.filter((r: any) => r.pm_status === 'In Review').length, label: 'In Review' },{ value: data.filter((r: any) => r.pm_status === 'Released').length, label: 'Released' }]} />
      <SearchBar />
      {!filtered.length ? <EmptyState msg="No releases found" /> : (
        <table className="data-table"><thead><tr><th>Release</th><th>Status</th><th>Release Date</th><th>Cutoff</th><th>Items</th><th>Actions</th></tr></thead>
        <tbody>{filtered.map((rel: any) => {
          const ri = items.filter((i: any) => i.pm_release === rel.id)
          const approved = ri.filter((i: any) => i.pm_signoff_status === 'Approved').length
          const isExp = expanded.has(rel.id)
          return (<Fragment key={rel.id}>
            <tr className={`data-row${isExp ? ' project-row-expanded' : ''} project-main-row`} onClick={() => toggle(rel.id)} style={{ cursor: 'pointer' }}><td><strong>{rel.pm_releasename}</strong><br /><small>{rel.pm_description?.substring(0, 60)}</small></td><td><span className={`badge ${badgeClass(rel.pm_status)}`}>{rel.pm_status}</span></td><td>{rel.pm_releasedate || '—'}</td><td>{rel.pm_cutoffdate || '—'}</td><td>{ri.length} items ({approved} approved)</td><td className="actions-cell" onClick={e => e.stopPropagation()}>
              {rel.pm_status === 'Draft' && <button className="btn-sm btn-link" onClick={() => openRelease(rel.id)}>🔓 Open</button>}
              {rel.pm_status === 'Open' && <><button className="btn-sm btn-link" onClick={() => registerStory(rel.id)}>➕ Register</button><button className="btn-sm btn-link" onClick={() => reviewRelease(rel.id)}>🔍 Review</button></>}
              {rel.pm_status === 'In Review' && <button className="btn-sm btn-edit" onClick={() => completeRelease(rel.id)}>✅ Complete</button>}
              <button className="btn-sm btn-edit" onClick={() => { const rec = DS.getById('pm_release', rel.id); showModal({ title: 'Edit Release', fields: getFields('pm_release'), data: rec, onSave: (fd) => { DS.update('pm_release', rel.id, fd); reload(); showToast('Release updated!') }, onDelete: () => { DS.delete('pm_release', rel.id); reload(); showToast('Release deleted!') } }) }}>✏️ Edit</button>
              <button className="btn-sm btn-delete" onClick={() => { if (confirm('Delete this release?')) { DS.delete('pm_release', rel.id); reload(); showToast('Release deleted!') } }}>🗑️</button>
            </td></tr>
            {isExp && ri.map((i: any) => { const story = stories.find((s: any) => s.id === i.pm_userstory); return (<tr key={i.id} className="project-epic-row"><td colSpan={6}><div className="project-epic-item"><span className={`badge ${badgeClass(i.pm_signoff_status)}`}>{i.pm_signoff_status}</span><span className="project-epic-name">{story?.pm_detail?.substring(0, 70) || '—'}</span><span className="project-epic-meta">By: {i.pm_registered_by || '—'} on {i.pm_registered_date || '—'}</span>{i.pm_signoff_by && <span className="project-epic-devs">Signoff: {i.pm_signoff_by} {i.pm_signoff_note ? `— ${i.pm_signoff_note}` : ''}</span>}{i.pm_signoff_status === 'Pending' && <button className="btn-sm btn-edit" onClick={() => showSignoffModal(i.id)}>✍️ Signoff</button>}</div></td></tr>) })}
            {isExp && ri.length === 0 && <tr className="project-epic-row"><td colSpan={6} style={{ padding: '10px 14px 10px 44px', color: 'var(--text-muted)', fontSize: '0.85rem' }}>No items registered</td></tr>}
          </Fragment>)
        })}</tbody></table>
      )}
    </div>
  )
}

function ConfigView() {
  const [data, setData] = useState<any[]>([]); const [key, setKey] = useState(0); const [typeFilter, setTypeFilter] = useState(''); const reload = () => setKey(k => k + 1); const { showToast, showModal } = useUI()
  useEffect(() => { setData(DS.getAll('pm_config')) }, [key])
  const { term } = useSearch()
  const filtered = (term ? data.filter((c: any) => Object.values(c).some(v => String(v ?? '').toLowerCase().includes(term.toLowerCase()))) : data).filter((c: any) => !typeFilter || c.pm_type === typeFilter)
  const types = ['value_stream', 'team', 'department', 'enhancement_type', 'capability_type', 'governance_status', 'priority', 'rag_status', 'requirement_status', 'psc_approval_status', 'signoff_status']
  const columns: ColumnDef[] = [{ field: 'pm_type', label: 'Type', format: 'badge' },{ field: 'pm_name', label: 'Name' },{ field: 'pm_description', label: 'Description' }]
  const actions: ActionDef[] = [{ id: 'edit', label: '✏️ Edit', cls: 'edit', onClick: (id) => { const rec = DS.getById('pm_config', id); showModal({ title: 'Edit Config', fields: getFields('pm_config'), data: rec, onSave: (fd) => { DS.update('pm_config', id, fd); reload(); showToast('Config updated!') }, onDelete: () => { DS.delete('pm_config', id); reload(); showToast('Config deleted!') } }) } },{ id: 'delete', label: '🗑️', cls: 'delete', onClick: (id) => { if (confirm('Delete this config entry?')) { DS.delete('pm_config', id); reload(); showToast('Config deleted!') } } }]
  return (<div><div className="dashboard-header"><h2>⚙️ Configuration</h2><button className="btn btn-primary" onClick={() => showModal({ title: 'New Config', fields: getFields('pm_config'), onSave: (fd) => { DS.create('pm_config', fd); reload(); showToast('Config created!') } })}>+ New Config</button></div><StatsCards stats={[{ value: data.length, label: 'Total' },{ value: data.filter((c: any) => c.pm_type === 'value_stream').length, label: 'Val. Streams' },{ value: data.filter((c: any) => c.pm_type === 'team').length, label: 'Teams' },{ value: data.filter((c: any) => c.pm_type === 'capability_type').length, label: 'Cap. Types' },{ value: data.filter((c: any) => c.pm_type === 'governance_status').length, label: 'Gov. Status' },{ value: data.filter((c: any) => c.pm_type === 'priority').length, label: 'Priorities' }]} /><div className="filter-bar" style={{ gap: 10 }}><SearchBar /><select className="btn-sm btn-reset" value={typeFilter} onChange={e => setTypeFilter(e.target.value)} style={{ padding: '8px 14px' }}><option value="">All Types</option>{types.map(t => <option key={t} value={t}>{t.replace(/_/g, ' ')}</option>)}</select></div><DataTable columns={columns} data={filtered} actions={actions} /></div>)
}

function RoadmapView() {
  const [viewMode, setViewMode] = useState<'month' | 'week' | 'day'>('month'); const [currentDate, setCurrentDate] = useState(new Date()); const { showToast, showModal } = useUI()
  const projects = useMemo(() => DS.getAll('pm_project'), [])
  const items: TimelineItem[] = useMemo(() => { const r: TimelineItem[] = []; for (const p of projects) { if (p.pm_startdate || p.pm_targetdeliverydate) r.push({ id: p.id, name: p.pm_name, type: 'project', status: p.pm_status || 'Not Started', start: p.pm_startdate || p.pm_targetdeliverydate, end: p.pm_targetdeliverydate || p.pm_startdate, completion: p.pm_overallcompletion || 0, priority: p.pm_priority || '' }) }; return r }, [projects])
  const navLabel = useMemo(() => { const m = currentDate.toLocaleString('default', { month: 'long' }); const y = currentDate.getFullYear(); if (viewMode === 'month') return `${m} ${y}`; if (viewMode === 'week') { const s = new Date(currentDate); s.setDate(s.getDate() - ((s.getDay() + 6) % 7)); const e = new Date(s); e.setDate(e.getDate() + 6); return `${s.toLocaleString('default', { month: 'short', day: 'numeric' })} – ${e.toLocaleString('default', { month: 'short', day: 'numeric', year: 'numeric' })}` }; return currentDate.toLocaleString('default', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' }) }, [viewMode, currentDate])
  const navigate = (dir: number) => { const d = new Date(currentDate); if (viewMode === 'month') d.setMonth(d.getMonth() + dir); else if (viewMode === 'week') d.setDate(d.getDate() + dir * 7); else d.setDate(d.getDate() + dir); setCurrentDate(d) }
  const handleItemClick = (id: string, _type: string) => { const rec = DS.getById('pm_project', id); if (!rec) { showToast('Item not found', 'error'); return }; showModal({ title: `📁 ${rec.pm_name || rec.pm_title}`, fields: [], extraContent: (<div className="detail-section"><p><strong>Status:</strong> {rec.pm_status || '—'}</p><p><strong>Start:</strong> {rec.pm_startdate || '—'} → <strong>Target:</strong> {rec.pm_targetdeliverydate || '—'}</p><p><strong>Completion:</strong> {rec.pm_overallcompletion || 0}% | <strong>Priority:</strong> {rec.pm_priority || '—'}</p>{rec.pm_scope && <p><strong>Scope:</strong> {rec.pm_scope}</p>}</div>), onSave: () => {} }) }
  const ndj = projects.filter((p: any) => !p.pm_startdate && !p.pm_targetdeliverydate); const ndi = [{ name: 'All products (dates removed)', type: 'Product' }, ...ndj.map((p: any) => ({ name: p.pm_name, type: 'Project' }))]
  return (<div><div className="dashboard-header"><h2>🗓️ Roadmap</h2><div className="roadmap-controls"><div className="roadmap-nav"><button className="btn-sm btn-reset" onClick={() => navigate(-1)}>◀</button><span className="roadmap-nav-label">{navLabel}</span><button className="btn-sm btn-reset" onClick={() => navigate(1)}>▶</button><button className="btn-sm btn-reset" onClick={() => setCurrentDate(new Date())}>Today</button></div><div className="roadmap-views">{(['month', 'week', 'day'] as const).map(v => (<button key={v} className={`btn-sm ${viewMode === v ? 'btn-primary' : 'btn-reset'}`} onClick={() => setViewMode(v)}>{v.charAt(0).toUpperCase() + v.slice(1)}</button>))}</div></div></div><StatsCards stats={[{ value: items.length, label: 'On Roadmap' },{ value: items.filter(i => i.type === 'product').length, label: 'Products' },{ value: items.filter(i => i.type === 'project').length, label: 'Projects' },{ value: items.filter(i => { const e = new Date(i.end || ''); return e < new Date() && i.status !== 'Live' && i.status !== 'Approved' }).length, label: 'Overdue' }]} /><div className="roadmap-legend"><span className="legend-item"><span className="legend-dot legend-product" /> Product</span><span className="legend-item"><span className="legend-dot legend-project" /> Project</span><span className="legend-item"><span className="legend-dot legend-completed" /> Completed</span><span className="legend-item"><span className="legend-dot legend-inprogress" /> In Progress</span><span className="legend-item"><span className="legend-dot legend-pending" /> Pending</span></div>{viewMode === 'month' && <MonthCalendar items={items} date={currentDate} onItemClick={handleItemClick} />}{viewMode === 'week' && <WeekCalendar items={items} date={currentDate} onItemClick={handleItemClick} />}{viewMode === 'day' && <DayCalendar items={items} date={currentDate} onItemClick={handleItemClick} />}{ndi.length > 0 && (<div className="roadmap-nodates"><h4>📌 Items Without Dates ({ndi.length})</h4><div className="roadmap-nodates-list">{ndi.map((i, idx) => <span key={idx} className="roadmap-nodate-item"><span className="badge badge-gray">{i.type}</span> {i.name}</span>)}</div></div>)}</div>)
}

const TABS = [{ id: 'resources', label: '👥 Resources' },{ id: 'products', label: '📦 Products' },{ id: 'projects', label: '📁 Projects' },{ id: 'capabilities', label: '🎯 Capabilities' },{ id: 'requirements', label: '📋 Requirements' },{ id: 'epics', label: '⚡ Epics' },{ id: 'stories', label: '📝 Stories' },{ id: 'risks', label: '⚠️ Risks' },{ id: 'dependencies', label: '🔗 Deps' },{ id: 'releases', label: '🚀 Releases' },{ id: 'roadmap', label: '🗓️ Roadmap' },{ id: 'config', label: '⚙️ Config' }]

function App() {
  const [tab, setTab] = useState('resources')
  const handleReset = () => { if (!confirm('Reset all data?')) return; localStorage.clear(); seedAllIfNeeded(); window.location.reload() }
  const renderTab = () => { switch (tab) { case 'resources': return <ResourcesView />; case 'products': return <ProductsView />; case 'projects': return <ProjectsView />; case 'capabilities': return <CapabilitiesView />; case 'requirements': return <RequirementsView />; case 'epics': return <EpicsView />; case 'stories': return <UserStoriesView />; case 'risks': return <RisksView />; case 'dependencies': return <DependenciesView />; case 'releases': return <ReleasesView />; case 'config': return <ConfigView />; case 'roadmap': return <RoadmapView />; default: return <ResourcesView /> } }
  return (<div className="app-root"><header className="app-header"><h1>Project Management Tool</h1><span className="badge-mode mode-dev">DEV</span><button className="btn-sm btn-reset" onClick={handleReset} style={{ marginLeft: 'auto' }}>🔄 Reset</button></header><nav className="tab-nav">{TABS.map(t => (<button key={t.id} className={`tab-btn ${tab === t.id ? 'active' : ''}`} onClick={() => setTab(t.id)}>{t.label}</button>))}</nav><main className="main-content">{renderTab()}</main></div>)
}

function AppWithProviders() { return (<SearchProvider><UIProvider><App /></UIProvider></SearchProvider>) }

export default AppWithProviders
export { App }
export { DS, seedAllIfNeeded, badgeClass, roadmapClass, getFields, getModelName, genId, MODELS }
